# owner: platform
"""Contact sheet rows for substitute teachers."""

from operator import attrgetter

def _check(students):
    if not students:
        raise ValueError("no students given")
    for pupil in students:
        if not pupil.email:
            raise ValueError(
                f"no email for {pupil.display_name}")

def _cells(students):
    ordered = sorted(
        students, key=attrgetter("display_name"))
    return [
        (pupil.display_name, pupil.section, pupil.email)
        for pupil in ordered
    ]

def _line(row, widths):
    return "  ".join(
        text.ljust(wide) for text, wide in zip(row, widths)
    ).rstrip()

# ---
def contact_rows(students):
    _check(students)
    cells = _cells(students)
    widths = [max(map(len, col)) for col in zip(*cells)]
    return [_line(row, widths) for row in cells]

