# owner: platform
import unittest

from rosterkit.contacts import contact_rows
from rosterkit.models import Student

def _pupil(last, first, section, email):
    return Student("1", last, first, section, email)

class ContactRowsTests(unittest.TestCase):
    def test_sorted_and_aligned(self):
        rows = contact_rows([
            _pupil("Young", "Al", "B", "al@x.org"),
            _pupil("Adams", "Bobbie", "A", "bob@x.org"),
        ])
        self.assertEqual(rows, [
            "Adams, Bobbie  A  bob@x.org",
            "Young, Al      B  al@x.org",
        ])

    def test_missing_email_names_student(self):
        bad = _pupil("Young", "Al", "B", None)
        with self.assertRaisesRegex(
                ValueError, "Young, Al"):
            contact_rows([bad])

    def test_empty_list(self):
        with self.assertRaises(ValueError):
            contact_rows([])

if __name__ == "__main__":
    unittest.main()
